import{_ as e,o,c as s,g as t}from"./chunks/framework.CNTkXYA8.js";const f=JSON.parse('{"title":"第一篇博客","description":"","frontmatter":{"title":"第一篇博客","date":"2024-10-13T20:48:40.000Z","tags":null},"headers":[],"relativePath":"blog/firstblog.md","filePath":"source/_posts/firstblog.md"}'),r={name:"blog/firstblog.md"};function n(a,l,p,c,u,d){return o(),s("div",null,[...l[0]||(l[0]=[t("p",null,"这是一条来自2024年10月13的简短信息，用来保存一点感想。",-1),t("p",null,"距我上次提到博客二字，已经过去一年时间；距我退役则两年了。忆往昔摸鱼时，见某篇题解作者在自己的退役博文里写道：“虽然我今天退役了，但在不久后，我将重新拾起键盘，为那些似曾相识的算法和梦想而敲击。”",-1),t("p",null,"那时认为我永远不会放下键盘，但我错了。因为一些原因，我花费了人生的一年半投入到与编码毫无关系的生活里。直到现在我发现：哪怕我在高中时即使踮起脚尖也望不到天才们的殿堂的台阶，编码仍然是我生活中不可或缺的一部分，进而是我灵魂中的不可或缺的一部分，这一点是无法改变的。编程这件事，我知道我会，而且擅长，这就够了，毋需借口。",-1),t("p",null,"言归正传，许久未写博客令我越来越感受到书写博客之理清逻辑、知识分享、养心怡神的重要性，而旧的cnblogs已经不能满足我对美观、编辑便捷性和完全可控的要求，便用hexo搭建了一个博客，就是现在你我在看的这个；我下载了butterfly主题，但是由于对前端技术一窍不通，很多美化的部分还需要折腾折腾。",-1),t("p",null,"新的博客象征着新的开始！来吧！",-1),t("p",null,"old blog: www.cnblogs.com/dudujerry",-1)])])}const g=e(r,[["render",n]]);export{f as __pageData,g as default};
